use verus::prelude::*;

verus! {
    /// Swap the first and last elements of a non‐empty vector in place.
    ///
    /// Requirements:
    ///   - a.len() ≥ 1
    ///
    /// Guarantees:
    ///   - The length is unchanged.
    ///   - The new first element equals the old last element.
    ///   - The new last element equals the old first element.
    ///   - All elements strictly between the first and last are unchanged.
    pub fn swap_first_and_last(a: &mut Vec<i32>)
        requires
            a.len() >= 1
        ensures
            // length unchanged
            a.len() == old(a.len()) &&
            // first and last have been swapped
            a[0] == old(a[a.len() - 1]) &&
            a[a.len() - 1] == old(a[0]) &&
            // all middle elements are unchanged
            forall |i: usize| 0 < i && i < a.len() - 1 ==> a[i] == old(a[i])
    {
        let last_index = a.len() - 1;
        let tmp = a[0];
        a[0] = a[last_index];
        a[last_index] = tmp;
    }
}

